/* @lc app=leetcode id=2468 lang=kotlin */
class Solution { fun splitMessage(message: String, limit: Int): Array<String> = (1..message.length).asSequence().map { n -> Triple(n, (1..n).sumOf { i -> i.toString().length }, n.toString().length) }.filter { (n, sumI, lenN) -> limit - 3 - lenN > 0 && n * (limit - 3 - lenN) - sumI >= message.length }.firstOrNull()?.let { (n, sumI, lenN) -> IntArray(1).let { offset -> Array(n) { i -> (i + 1).let { cur -> (limit - 3 - cur.toString().length - lenN).let { canTake -> message.substring(offset[0], (offset[0] + canTake).coerceAtMost(message.length)).let { sub -> "$sub<${cur}/$n>".also { offset[0] += sub.length } } } } } } } ?: emptyArray() }